  /**
   * allBoostHistories iterates over GET /v1/hosting/web/{serviceName}/boostHistory (List boost history).
   *
   * It lists the IDs with {@link HostingwebApi.listBoostHistories}, then gets each object with
   * {@link HostingwebApi.getBoostHistory}, only when the loop reaches it. An object deleted in the
   * meantime is skipped. Any other error is thrown and stops the loop.
   *
   * The two calls require the IAM action webHosting:apiovh:boostHistory/get.
   *
   * @param serviceName - Service name
   * @param params - the optional parameters
   * @param options - the options of this call: signal, timeout, headers
   * @returns each {@link models.HostingWebBoostHistoryAlt}, one at a time: loop with `for await`
   * @throws ForbiddenError when the policy lacks an IAM action this call requires
   * @example
   * for await (const item of client.hostingweb.allBoostHistories(serviceName)) console.log(item);
   */
  allBoostHistories(
    serviceName: string,
    params?: {
      /** Filter the value of date property (=) */
      date?: string | undefined;
    },
    options?: RequestOptions,
  ): AsyncIterable<models.HostingWebBoostHistoryAlt> {
    return this._each(
      () => this.listBoostHistories(serviceName, params, options),
      (listedId) => this.getBoostHistory(serviceName, listedId, options),
    );
  }

